SELECT COALESCE(SUM(amount), 0)
FROM t_account_flow
WHERE student_id = #{studentId}
AND flow_type = #{flowType}

    AND DATE(create_time) >= DATE(#{startTime})


    AND DATE(create_time) <= DATE(#{endTime})
